class DanShinyButton{static instances=[];constructor(element){Object.assign(this,{element,effectsContainer:element.querySelector('.dan-shiny-button__effects'),eventListeners:[]});this.initialize()}
initialize(){this.element.removeAttribute("data-flickering");this.setupMouseEffects()}
setupMouseEffects(){const handlePointerMove=(e)=>{const rect=this.element.getBoundingClientRect();const mouseX=(e.clientX-rect.left)/rect.width;const mouseY=(e.clientY-rect.top)/rect.height;this.effectsContainer.style.setProperty('--mx',`${mouseX * 100}%`);this.effectsContainer.style.setProperty('--my',`${mouseY * 100}%`)};this.element.addEventListener('pointermove',handlePointerMove);this.eventListeners.push({element:this.element,type:'pointermove',listener:handlePointerMove})}
destroy(){this.eventListeners.forEach(({element,type,listener})=>{element.removeEventListener(type,listener)});this.eventListeners=[];if(this.effectsContainer){this.effectsContainer.style.removeProperty('--mx');this.effectsContainer.style.removeProperty('--my')}}
static destroyAll(){DanShinyButton.instances.forEach((instance)=>instance.destroy());DanShinyButton.instances=[]}}
const dancepad_shiny_button=()=>{DanShinyButton.destroyAll();const instances=[];document.querySelectorAll(".dan-shiny-button").forEach((element)=>{const instance=new DanShinyButton(element);instances.push(instance)});DanShinyButton.instances=instances}